<?php
declare(strict_types=1);
/** Phase 4 tests: brand + catalogue designer, product cards, the customer catalogue page, the order form with Confirm / Cancel, hand-back to the AI, setup-guide saving. Included by tests/run.php. */
use CaliChat\Core\{Db, Tenant};
use CaliChat\Services\{Brand, Catalogue, Chat, Interactive, Jobs, OrderFlow, Queue, Store, ToolRunner};

echo "\nPhase 4: branded cards and catalogue, order form, hand-back, setup guide\n";
$stubLog4 = fn() => is_file(sys_get_temp_dir() . '/cc_graph_stub.log') ? array_map(fn($l) => json_decode($l, true), file(sys_get_temp_dir() . '/cc_graph_stub.log', FILE_IGNORE_NEW_LINES)) : [];
$mk4 = function (string $name) { $v = mkTenant($name); Store::seedSample($v['tid']); Store::connect($v['tid']); return $v; };
$png4 = function (int $w = 120, int $hh = 60) { $i = imagecreatetruecolor($w, $hh); imagefill($i, 0, 0, imagecolorallocate($i, 200, 30, 60)); $f = tempnam(sys_get_temp_dir(), 'lg') . '.png'; imagepng($i, $f); return $f; };
$path4 = fn(string $url) => preg_replace('#^https?://[^/]+#', '', $url);

t('brand: settings are validated, the logo is re-encoded and served publicly, unsafe images are refused', function () use ($png4, $h) {
    $v = mkTenant('Brand'); $tid = $v['tid']; $b = Brand::get($tid); eq($b['name'], 'Brand'); eq($b['cat_layout'], 'list', 'the WhatsApp-style list is the default'); eq($b['has_logo'], false);
    Brand::save($tid, ['brand_name' => '  Calico <b>Co</b>  ', 'brand_color' => 'red; background:url(x)', 'cat_columns' => 9, 'cat_layout' => 'carousel', 'cat_theme' => 'dark', 'cat_button' => '', 'cat_featured' => 'ts-001, <x>, sh-221', '_catalogue_form' => 1, 'cat_show_desc' => 1]);
    $b = Brand::get($tid); eq($b['brand_color'], '#5B5BF0', 'a bad colour falls back'); eq($b['cat_columns'], 4, 'columns are clamped'); eq($b['cat_layout'], 'list', 'unknown layout falls back'); eq($b['cat_theme'], 'dark'); eq($b['cat_button'], 'Add to order'); eq($b['featured'], ['TS-001', 'X', 'SH-221'], 'featured SKUs keep only safe characters'); eq($b['cat_show_stock'], 0, 'an unticked box is off'); eq($b['cat_show_desc'], 1);
    $f = $png4(); eq(Brand::saveLogoFile($tid, $f), null); ok(is_file(Brand::logoPath($tid)) && Brand::get($tid)['has_logo'], 'logo saved'); $logo = Brand::get($tid)['logo_url'];
    $r = $h->req('GET', $logo ? preg_replace('#^https?://[^/]+#', '', $logo) : '/'); eq($r['code'], 200); ok(stripos($r['head'], 'image/png') !== false && strpos($r['body'], "\x89PNG") === 0, 'served as a PNG');
    $svg = tempnam(sys_get_temp_dir(), 'sv') . '.svg'; file_put_contents($svg, '<svg xmlns="http://www.w3.org/2000/svg"><script>alert(1)</script></svg>'); ok(Brand::saveLogoFile($tid, $svg) !== null, 'SVG is refused');
    $fake = tempnam(sys_get_temp_dir(), 'fk') . '.png'; file_put_contents($fake, '<?php echo 1;'); ok(Brand::saveLogoFile($tid, $fake) !== null, 'a script renamed to .png is refused');
    Tenant::saveSettings($tid, []); Db::update('tenants', ['status' => 'suspended'], 'id=?', [$tid]); eq($h->req('GET', preg_replace('#^https?://[^/]+#', '', $logo))['code'], 404, 'a suspended business serves nothing');
    Brand::removeLogo($tid); eq(Brand::get($tid)['has_logo'], false);
});

t('catalogue link: signed per customer, expires, tenant-bound; the page shows the design and never the cost price', function () use ($mk4, $h, $path4) {
    $v = $mk4('Shop'); $tid = $v['tid']; Brand::save($tid, ['brand_name' => 'Calico Wear', 'brand_tagline' => 'Dress well', 'cat_title' => 'Spring edit', 'cat_theme' => 'dark', 'cat_featured' => 'SH-221']); $other = $mk4('ShopTwo');
    $link = Catalogue::link($tid, '+94 77 123 4567'); $p = $path4($link); preg_match('#/shop/(\d+)/(\d+)/(\d+)/([\w-]+)#', $link, $m); eq($m[2], '94771234567', 'the phone is reduced to digits');
    $r = $h->req('GET', $p); eq($r['code'], 200); ok(strpos($r['body'], 'Calico Wear') !== false && strpos($r['body'], 'Spring edit') !== false && strpos($r['body'], '"theme":"dark"') !== false, 'the design is in the page');
    ok(strpos($r['body'], 'Cotton T-Shirt') !== false && strpos($r['body'], 'cost') === false, 'products yes, cost price never'); ok(stripos($r['head'], "frame-ancestors 'self'") !== false && stripos($r['head'], 'img-src') !== false, 'own CSP allows photos');
    preg_match('/"products":\[\{"sku":"([A-Z0-9-]+)"/', $r['body'], $first); eq($first[1], 'SH-221', 'featured products come first');
    eq($h->req('GET', "/shop/$tid/94771234567/{$m[3]}/AAAAAAAAAAAAAAAAAAAAAAAA")['code'], 404, 'forged signature'); eq($h->req('GET', "/shop/$tid/94770000000/{$m[3]}/{$m[4]}")['code'], 404, 'someone else\'s number'); eq($h->req('GET', "/shop/{$other['tid']}/94771234567/{$m[3]}/{$m[4]}")['code'], 404, 'another business');
    eq($h->req('GET', "/shop/$tid/94771234567/" . (time() - 5) . '/' . $m[4])['code'], 404, 'expired / altered expiry'); $old = time() - 10; $sigOld = (new ReflectionClass(Catalogue::class))->getMethod('sig'); $sigOld->setAccessible(true);
    eq($h->req('GET', "/shop/$tid/94771234567/$old/" . $sigOld->invoke(null, $tid, '94771234567', $old))['code'], 404, 'a correctly signed but expired link');
    $cat = $path4(Catalogue::link($tid, '94771234567', 'Footwear')); ok(strpos($h->req('GET', $cat)['body'], '"category":"Footwear"') !== false, 'opens on the asked category');
    Db::update('store_products', ['is_active' => 0], 'tenant_id=? AND sku=?', [$tid, 'TS-001']); ok(strpos($h->req('GET', $p)['body'], 'Cotton T-Shirt') === false, 'hidden products are not listed'); Brand::save($tid, ['_catalogue_form' => 1, 'cat_hide_categories' => ['Footwear']]);
    ok(strpos($h->req('GET', $p)['body'], 'Canvas Sneakers') === false, 'hidden categories are not listed');
});

t('catalogue: the cart is priced by the server with the delivery fee; Confirm places the order once; nothing can be forged', function () use ($mk4, $h, $path4) {
    $v = $mk4('Cart'); $tid = $v['tid']; $link = $path4(Catalogue::link($tid, '94771110001')); $post = fn($u, $d) => $h->req('POST', $u, json_encode($d), ['Content-Type: application/json']);
    $cart = [['sku' => 'TS-001', 'size' => 'M', 'color' => 'Black', 'qty' => 2], ['sku' => 'AC-503', 'size' => '', 'color' => 'Khaki', 'qty' => 1]];
    $q = json_decode($post("$link/quote", ['cart' => $cart, 'city' => 'Kandy', 'payment' => 'Cash on delivery'])['body'], true); ok($q['ok']); eq((float)$q['subtotal'], 1850 * 2 + 1500.0); eq((float)$q['delivery_fee'], 450.0, 'Kandy delivery'); eq((float)$q['total'], 5650.0); eq($q['problems'], []); eq(count($q['lines']), 2);
    $free = json_decode($post("$link/quote", ['cart' => [['sku' => 'WT-700', 'size' => '', 'color' => 'Gold', 'qty' => 1]], 'city' => 'Colombo'])['body'], true); eq((float)$free['delivery_fee'], 0.0, 'free delivery over the threshold'); eq((float)$free['total'], 12900.0);
    $bad = json_decode($post("$link/quote", ['cart' => [['sku' => 'TS-001', 'size' => 'M', 'color' => 'Black', 'qty' => 500]], 'city' => 'Kandy'])['body'], true); ok($bad['ok'] === false || $bad['problems'] !== [], 'quantity above 99 / stock is refused');
    $oos = json_decode($post("$link/quote", ['cart' => [['sku' => 'SC-050', 'size' => '', 'color' => 'Red', 'qty' => 1]], 'city' => 'Kandy'])['body'], true); ok(strpos(json_encode($oos['problems']), 'stock') !== false, 'sold out items are flagged');
    $ct = Chat::contact($tid, 0, 'whatsapp', '94771110001', 'Kamal', '94771110001'); $conv = Chat::conversation($tid, null, 'whatsapp', $ct, null);
    $in = ['cart' => $cart, 'name' => 'Kamal Perera', 'address' => '12 Temple Rd', 'city' => 'Kandy', 'payment' => 'Cash on delivery', 'nonce' => 'abc123'];
    $stock0 = (int)Db::val("SELECT stock FROM store_products WHERE tenant_id=? AND sku='TS-001'", [$tid]); $r = json_decode($post("$link/order", $in)['body'], true); ok($r['ok'], json_encode($r)); eq((float)$r['order']['total'], 5650.0); ok(preg_match('/^ORD-\d+$/', $r['order']['order_no']) === 1); ok(strpos($r['order']['invoice_url'], '/invoice/') !== false);
    $o = Store::order($tid, $r['order']['order_no']); eq($o['source'], 'catalogue'); eq($o['phone'], '94771110001', 'the phone comes from the link, not the request'); eq((float)$o['delivery_fee'], 450.0); eq((int)Db::val("SELECT stock FROM store_products WHERE tenant_id=? AND sku='TS-001'", [$tid]), $stock0 - 2, 'stock is taken');
    $again = json_decode($post("$link/order", $in)['body'], true); eq($again['order']['order_no'], $r['order']['order_no'], 'a double tap returns the same order'); eq((int)Db::val("SELECT COUNT(*) FROM store_orders WHERE tenant_id=?", [$tid]), 1, 'and places only one');
    $msg = Db::one("SELECT content, meta FROM messages WHERE conversation_id=? AND sender='ai' ORDER BY id DESC LIMIT 1", [$conv['id']]); ok($msg && strpos($msg['content'], $r['order']['order_no']) !== false && strpos($msg['content'], 'Delivery') !== false, 'the chat gets the confirmation'); ok(strpos((string)$msg['meta'], 'tool_notes') !== false, 'and the AI can see the order');
    foreach ([['name' => ''], ['address' => 'x'], ['city' => ''], ['payment' => ''], ['cart' => []], ['cart' => [['sku' => "X'; DROP TABLE x;--", 'qty' => 1]]], ['payment' => 'Barter']] as $i => $patch) { $x = json_decode($post("$link/order", array_merge($in, $patch, ['nonce' => 'n' . $i]))['body'], true); ok($x['ok'] === false && !empty($x['error']), 'rejected: ' . json_encode($patch)); }
    eq((int)Db::val("SELECT COUNT(*) FROM store_orders WHERE tenant_id=?", [$tid]), 1, 'none of the bad requests placed an order');
    $pv = $path4(Catalogue::previewLink($tid)); eq($post("$pv/order", $in)['code'], 403, 'a preview link cannot place orders'); eq($post("$pv/quote", $in)['code'], 200, 'but can price');
    $badLink = preg_replace('#/[\w-]+$#', '/ZZZZZZZZZZZZZZZZZZZZZZZZ', $link); eq($post("$badLink/order", $in)['code'], 404, 'a forged link cannot order');
    Db::update('tenants', ['settings' => json_encode(['store_max_total' => 3000])], 'id=?', [$tid]); $big = json_decode($post($path4(Catalogue::link($tid, '94771110009')) . '/order', array_merge($in, ['nonce' => 'big1']))['body'], true); eq(json_decode($post("$link/order", array_merge($in, ['nonce' => 'rl']))['body'], true)['ok'] ?? null, false, 'rate limited or refused'); ok($big['ok'] === false && strpos((string)$big['error'], 'limit') !== false, 'the online order limit applies to catalogue orders too: ' . json_encode($big));
});

t('order form: a server-built summary with the delivery fee and Confirm / Cancel buttons in the customer\'s language', function () use ($mk4, $waChannel, $stubLog4) {
    $v = $mk4('Form'); $tid = $v['tid']; $contact = ['phone' => '94771110002', 'external_id' => '94771110002', 'name' => 'Nimali'];
    $args = ['items' => 'TS-001:M:2:Black,AC-503:-:1:Khaki', 'delivery_city' => 'Kandy', 'delivery_address' => '5 Hill St', 'payment_method' => 'Cash on delivery', 'customer_name' => 'Nimali'];
    $s = OrderFlow::summary($tid, 'create_order', $args, $contact, 'place the order please'); ok($s !== null); $tx = $s['text'];
    foreach (['Order summary', '2 × Cotton T-Shirt (M, Black)', 'Baseball Cap (Khaki)', 'Subtotal: Rs. 5,200', 'Delivery (Kandy): Rs. 450', 'Total: Rs. 5,650', 'Payment: Cash on delivery', '5 Hill St', 'Form'] as $needle) ok(strpos($tx, $needle) !== false, "summary has: $needle\n$tx");
    ok(mb_strlen($tx) < 900, 'fits a WhatsApp button message'); $dup = OrderFlow::summary($tid, 'create_order', array_merge($args, ['delivery_address' => '5 Hill St, Kandy']), $contact, 'ok'); ok(strpos($dup['text'], 'Kandy, Kandy') === false && strpos($dup['text'], 'Nimali, 5 Hill St, Kandy') !== false, 'the town is not printed twice'); eq($s['total'], 5650.0);
    $free = OrderFlow::summary($tid, 'create_order', ['items' => 'WT-700:-:1:Gold'] + $args, $contact, 'ok'); ok(strpos($free['text'], 'FREE') !== false, 'free delivery says so');
    eq(OrderFlow::summary($tid, 'create_order', array_merge($args, ['delivery_address' => '']), $contact, 'ok'), null, 'incomplete details: no summary form'); eq(OrderFlow::summary($tid, 'create_order', array_merge($args, ['items' => 'NOPE-1:-:1']), $contact, 'ok'), null, 'unknown product: no summary form');
    $si = OrderFlow::summary($tid, 'create_order', $args, $contact, 'ඇණවුම තබන්න'); eq($si['lang'], 'si'); ok(strpos($si['text'], 'ඇණවුම් සාරාංශය') !== false && strpos($si['text'], 'Rs. 5,650') !== false, 'Sinhala labels, same numbers'); eq(OrderFlow::buttons('ta')[0]['title'], 'உறுதிப்படுத்து');
    foreach (['en', 'si', 'ta'] as $lg) foreach (OrderFlow::buttons($lg) as $b) ok(mb_strlen($b['title']) <= 20, "$lg button fits Meta's 20 characters"); eq(array_column(OrderFlow::buttons('en'), 'id'), ['order_confirm', 'order_cancel']);
    $ch = Db::one("SELECT * FROM channels WHERE id=?", [$waChannel($tid, '8101')]); Brand::saveLogoFile($tid, (function () { $i = imagecreatetruecolor(80, 40); $f = tempnam(sys_get_temp_dir(), 'lg') . '.png'; imagepng($i, $f); return $f; })());
    $tenant = Tenant::get($tid); $rich = Interactive::forReply($tenant, $ch, ['order_summary' => $s, 'awaiting_confirmation' => true], $tx . "\n\n" . OrderFlow::t('en', 'ask')); eq(array_column($rich['buttons'], 'id'), ['order_confirm', 'order_cancel']); ok(strpos((string)$rich['header'], '/media/logo/' . $tid) !== false, 'the business logo heads the form'); eq($rich['footer'], 'Form');
    eq(Interactive::forReply($tenant, array_merge($ch, ['type' => 'messenger']), ['order_summary' => $s], $tx), [], 'other channels get the text version');
    @unlink(sys_get_temp_dir() . '/cc_graph_stub.log'); ok(Interactive::deliver($ch, '94771110002', $tx, $rich)['ok']); $sent = array_values(array_filter($stubLog4(), fn($x) => $x['p'] === '/8101/messages')); $i = $sent[0]['j']['interactive'];
    eq($i['type'], 'button'); eq($i['header']['type'], 'image'); eq($i['footer']['text'], 'Form'); eq(count($i['action']['buttons']), 2); ok(strpos($i['body']['text'], 'Rs. 5,650') !== false);
});

t('order form: Confirm places the order without asking the model; Cancel discards it; "Cancel order" is never an unsubscribe', function () use ($mk4, $waChannel, $stubLog4) {
    $v = $mk4('Tap'); $tid = $v['tid']; $chId = $waChannel($tid, '8102'); $channel = Db::one("SELECT * FROM channels WHERE id=?", [$chId]); $tenant = Tenant::get($tid); $phone = '94771110003';
    $contact = Chat::contact($tid, $chId, 'whatsapp', $phone, 'Sunil', $phone); $conv = Chat::conversation($tid, $channel, 'whatsapp', $contact, null);
    $tool = Db::one("SELECT * FROM tools WHERE tenant_id=? AND name='create_order'", [$tid]); $args = ['items' => 'TS-001:M:1:Black', 'delivery_city' => 'Colombo', 'delivery_address' => '9 Lake Rd', 'payment_method' => 'Cash on delivery', 'customer_name' => 'Sunil'];
    $deliver = function ($t, $rich = []) { return ['ok' => true]; };
    $preview = function () use ($tid, $tool, $args, $conv, $contact, $phone) { Chat::addMessage($tid, (int)$conv['id'], 'in', 'customer', 'place my order'); $r = ToolRunner::run($tool, $args, $contact, (int)$conv['id']); eq($r['data']['status'], 'confirmation_required'); return $r; };
    eq(OrderFlow::handleTap($tenant, $channel, $contact, $conv, 'order_confirm', $deliver), null, 'no open summary: falls through to the normal path');
    $preview(); Chat::addMessage($tid, (int)$conv['id'], 'in', 'customer', 'Cancel order'); $res = OrderFlow::handleTap($tenant, $channel, $contact, $conv, 'order_cancel', $deliver); ok($res && strpos($res['reply'], 'discarded') !== false); eq((int)Db::val("SELECT COUNT(*) FROM store_orders WHERE tenant_id=?", [$tid]), 0, 'nothing was placed'); eq((int)Db::val("SELECT COUNT(*) FROM action_previews WHERE conversation_id=? AND used_at IS NULL", [$conv['id']]), 0, 'the preview is gone');
    $preview(); Chat::addMessage($tid, (int)$conv['id'], 'in', 'customer', 'Confirm order'); $stock0 = (int)Db::val("SELECT stock FROM store_products WHERE tenant_id=? AND sku='TS-001'", [$tid]);
    $res = OrderFlow::handleTap($tenant, $channel, $contact, $conv, 'order_confirm', $deliver); ok($res && !$res['error'], json_encode($res)); $o = Db::one("SELECT * FROM store_orders WHERE tenant_id=?", [$tid]); ok($o, 'the order exists'); eq($o['phone'], $phone); eq($o['source'], 'ai'); eq((int)Db::val("SELECT stock FROM store_products WHERE tenant_id=? AND sku='TS-001'", [$tid]), $stock0 - 1);
    ok(strpos($res['reply'], $o['order_no']) !== false && strpos($res['reply'], 'Total: Rs. 2,200') !== false && strpos($res['reply'], '/invoice/') !== false, 'the reply states the real order, total and invoice: ' . $res['reply']);
    $m = Db::one("SELECT meta FROM messages WHERE conversation_id=? AND sender='ai' ORDER BY id DESC LIMIT 1", [$conv['id']]); ok(strpos((string)$m['meta'], 'create_order') !== false, 'the AI sees what happened');
    eq(OrderFlow::handleTap($tenant, $channel, $contact, $conv, 'order_confirm', $deliver), null, 'a second tap cannot place it twice'); eq((int)Db::val("SELECT COUNT(*) FROM store_orders WHERE tenant_id=?", [$tid]), 1);
    // end to end through the queue: tapping "Cancel order" must not opt the customer out
    $preview(); Db::update('contacts', ['consent_status' => 'opted_in'], 'id=?', [$contact['id']]);
    ok(Queue::enqueue($channel, ['id' => 'wamid.tap1', 'sender' => $phone, 'name' => 'Sunil', 'phone' => $phone, 'type' => 'text', 'text' => 'Cancel order', 'media_ref' => null, 'mime' => null, 'reply_id' => 'order_cancel'])); Db::q("UPDATE inbound_events SET status='processing', attempts=1, locked_by='t4' WHERE provider_id='wamid.tap1' AND channel_id=?", [$chId]); $ev = Db::one("SELECT * FROM inbound_events WHERE provider_id='wamid.tap1' AND channel_id=?", [$chId]); ok($ev); Queue::runOne($ev);
    eq(Db::val("SELECT consent_status FROM contacts WHERE id=?", [$contact['id']]), 'opted_in', 'still opted in'); eq(Db::val("SELECT status FROM inbound_events WHERE id=?", [$ev['id']]), 'done'); eq((int)Db::val("SELECT COUNT(*) FROM action_previews WHERE conversation_id=? AND used_at IS NULL", [$conv['id']]), 0); eq((int)Db::val("SELECT COUNT(*) FROM store_orders WHERE tenant_id=?", [$tid]), 1, 'cancel placed nothing');
    $t = Catalogue::tapText($tid, 'add:TS-001', 'Add to order'); eq($t, 'Add to order: Cotton T-Shirt (TS-001)'); eq(Catalogue::tapText($tid, 'AC-503', 'Baseball Cap'), 'I am interested in: Baseball Cap (AC-503)'); eq(Catalogue::tapText($tid, 'more_products', 'More products'), 'Show me more products'); eq(Catalogue::tapText($tid, 'add:NOPE', 'Add to order'), 'Add to order', 'unknown products keep the tapped text');
});

t('product cards and catalogue: a branded card image with Add to order buttons on WhatsApp; a plain link everywhere else', function () use ($mk4, $waChannel, $stubLog4, $png4, $h, $path4) {
    $v = $mk4('Card'); $tid = $v['tid']; $chId = $waChannel($tid, '8103'); $phone = '94771110004'; Brand::save($tid, ['brand_name' => 'Calico Wear', 'brand_color' => '#0F766E', 'cat_title' => 'Spring edit']); Brand::saveLogoFile($tid, $png4(200, 80));
    $contact = Chat::contact($tid, $chId, 'whatsapp', $phone, 'Nadee', $phone); $conv = Chat::conversation($tid, Db::one("SELECT * FROM channels WHERE id=?", [$chId]), 'whatsapp', $contact, null);
    @unlink(sys_get_temp_dir() . '/cc_graph_stub.log'); $r = Catalogue::sendProductCard($tid, $contact, 'ts-001', false, (int)$conv['id']); eq($r['status'], 'sent'); $m = array_values(array_filter($stubLog4(), fn($x) => $x['p'] === '/8103/messages'))[0]['j']['interactive'];
    eq($m['type'], 'button'); eq($m['header']['type'], 'image'); ok(strpos($m['header']['image']['link'], '/media/card/' . $tid . '/TS-001') !== false, 'the branded card image is the header'); eq($m['footer']['text'], 'Calico Wear'); ok(strpos($m['body']['text'], 'Cotton T-Shirt') !== false && strpos($m['body']['text'], 'Rs. 1,850') !== false && strpos($m['body']['text'], 'Sizes: S, M, L, XL') !== false);
    eq(array_column(array_column($m['action']['buttons'], 'reply'), 'id'), ['add:TS-001', 'more_products']);
    $img = $h->req('GET', $path4($m['header']['image']['link'])); eq($img['code'], 200); ok(strpos($img['body'], "\x89PNG") === 0, 'the card is a PNG'); $sz = getimagesizefromstring($img['body']); eq([$sz[0], $sz[1]], [800, 920]); $png = Brand::cardPng($tid, Db::one("SELECT * FROM store_products WHERE tenant_id=? AND sku='TS-001'", [$tid]));
    $px = imagecreatefromstring($png); $c = imagecolorat($px, 400, 4); eq(sprintf('%06X', $c & 0xFFFFFF), '0F766E', 'the header bar carries the brand colour');
    eq($h->req('GET', '/media/card/' . $tid . '/NOPE-1')['code'], 404); Db::update('store_products', ['is_active' => 0], 'tenant_id=? AND sku=?', [$tid, 'JN-015']); eq($h->req('GET', '/media/card/' . $tid . '/JN-015')['code'], 404, 'hidden products have no public card');
    $sold = Catalogue::sendProductCard($tid, $contact, 'SC-050', false, (int)$conv['id']); eq($sold['status'], 'sent'); $last = array_values(array_filter($stubLog4(), fn($x) => $x['p'] === '/8103/messages')); eq(count(end($last)['j']['interactive']['action']['buttons']), 1, 'a sold-out product has no Add to order button');
    eq(Catalogue::sendProductCard($tid, $contact, 'NOPE', false, (int)$conv['id'])['status'], 'not_found');
    $c = Catalogue::sendCatalogue($tid, $contact, 'Footwear', false, (int)$conv['id']); eq($c['status'], 'sent'); $cm = end(array_values(array_filter($stubLog4(), fn($x) => $x['p'] === '/8103/messages')))['j']['interactive']; eq($cm['type'], 'cta_url'); ok(strpos($cm['action']['parameters']['url'], '/shop/' . $tid . '/' . $phone . '/') !== false && strpos($cm['action']['parameters']['url'], 'c=Footwear') !== false); ok(strpos($cm['body']['text'], 'Spring edit') !== false); eq($cm['footer']['text'], 'Calico Wear'); ok(strpos($cm['header']['image']['link'], '/media/logo/') !== false, 'the logo heads the catalogue message');
    $tw = Db::insert('channels', ['tenant_id' => $tid, 'type' => 'messenger', 'name' => 'FB', 'external_id' => 'pg1', 'verify_token' => 'v', 'channel_key' => bin2hex(random_bytes(8))]); $mc = Chat::contact($tid, $tw, 'messenger', 'psid1', 'Fb', null);
    $l = Catalogue::sendCatalogue($tid, $mc, null, false, (int)$conv['id']); eq($l['status'], 'link'); ok(strpos($l['url'], '/shop/' . $tid . '/') !== false); $pc = Catalogue::sendProductCard($tid, $mc, 'TS-001', false, (int)$conv['id']); eq($pc['status'], 'not_sent'); ok(isset($pc['product']['name']) && !isset($pc['product']['cost_price']), 'text fallback has the data, never the cost');
    $emptyT = mkTenant('NoStock'); eq(Catalogue::sendCatalogue($emptyT['tid'], $mc + ['channel_id' => null], null, false, 0)['status'], 'empty');
});

t('chat cards: the dashboard chats get the card data (not a bare link) and open the catalogue in a modal through a read-only preview link', function () use ($mk4, $h, $path4, $png4) {
    $v = $mk4('Rich'); $tid = $v['tid']; Brand::saveLogoFile($tid, $png4()); Brand::save($tid, ['brand_name' => 'Rich Wear', 'brand_color' => '#0F766E', 'brand_tagline' => 'Wear it']);
    $ct = Chat::contact($tid, 0, 'playground', 'pg-1-94770003333', 'Tester', '94770003333'); $conv = Chat::conversation($tid, null, 'playground', $ct, null);
    $p = Catalogue::sendProductCard($tid, $ct, 'ts-001', true, (int)$conv['id']); eq($p['status'], 'sent', 'shown in the chat, not "not sent"'); eq($p['rich']['type'], 'product'); eq([$p['rich']['sku'], $p['rich']['name'], (float)$p['rich']['price'], $p['rich']['brand'], $p['rich']['color']], ['TS-001', 'Cotton T-Shirt', 1850.0, 'Rich Wear', '#0F766E']); ok(strpos($p['rich']['logo'], 'media/logo/' . $tid) === 0 && strpos($p['rich']['logo'], 'http') !== 0, 'relative logo path'); ok(!isset($p['rich']['cost_price']) && strpos(json_encode($p), 'cost') === false);
    $m = Db::one("SELECT content, meta FROM messages WHERE conversation_id=? ORDER BY id DESC LIMIT 1", [$conv['id']]); ok(strpos($m['content'], '[Product card]') === 0 && json_decode($m['meta'], true)['rich']['sku'] === 'TS-001', 'saved on the message so the Inbox can draw it too');
    $c = Catalogue::sendCatalogue($tid, $ct, 'Footwear', true, (int)$conv['id']); eq($c['status'], 'sent'); eq($c['rich']['type'], 'catalogue'); eq($c['rich']['category'], 'Footwear'); eq($c['rich']['count'], 2); ok(count($c['rich']['items']) === 2 && isset($c['rich']['items'][0]['name']));
    $all = Catalogue::richCatalogue($tid, null); eq($all['count'], 12); eq(count($all['items']), 4, 'a 2x2 preview'); Brand::save($tid, ['_catalogue_form' => 1, 'cat_hide_categories' => ['Footwear']]); eq(Catalogue::richCatalogue($tid, null)['count'], 10, 'hidden categories are not counted');
    // the link API behind the modal
    $o = new Http('http://127.0.0.1:8765'); $o->login($v['email']); $cs = $o->meta(); $r = $o->api('POST', 'catalogue/link', ['sku' => 'TS-001'], $cs); eq($r['code'], 200); ok($r['json']['preview'] === true && strpos($r['json']['url'], '/shop/' . $tid . '/preview/') !== false && strpos($r['json']['url'], 'p=TS-001') !== false && strpos($r['json']['url'], 'http') !== 0, 'a relative, read-only preview URL: ' . $r['json']['url']);
    $page = $h->req('GET', $r['json']['url']); eq($page['code'], 200); ok(strpos($page['body'], '"focus":"TS-001"') !== false, 'the page opens on that product'); ok(stripos($page['head'], 'X-Frame-Options: SAMEORIGIN') !== false && stripos($page['head'], "frame-ancestors 'self'") !== false, 'it may be framed by the dashboard, only by our own origin');    $live = $o->api('POST', 'catalogue/link', ['sku' => 'TS-001', 'live' => 1, 'phone' => '94770003333'], $cs); ok($live['json']['preview'] === false && strpos($live['json']['url'], '/shop/' . $tid . '/94770003333/') !== false, 'owners get the customer\'s link for the Playground with write actions on'); eq($o->api('POST', 'catalogue/link', ['live' => 1, 'phone' => '12'], $cs)['code'], 422);
    $s = mkTenant('RichStaff', 'agent'); Db::update('users', ['tenant_id' => $tid], 'id=?', [$s['uid']]); $sc = new Http('http://127.0.0.1:8765'); $sc->login($s['email']); $scs = $sc->meta(); eq($sc->api('POST', 'catalogue/link', ['live' => 1, 'phone' => '94770003333'], $scs)['code'], 403, 'staff cannot mint a customer link'); eq($sc->api('POST', 'catalogue/link', ['sku' => 'TS-001'], $scs)['code'], 200, 'but can open the read-only preview');
    $other = mkTenant('RichOther'); $oc = new Http('http://127.0.0.1:8765'); $oc->login($other['email']); $x = $oc->api('POST', 'catalogue/link', ['sku' => 'TS-001'], $oc->meta()); ok(strpos($x['json']['url'], '/shop/' . $other['tid'] . '/') !== false && strpos($x['json']['url'], 'p=') === false, 'another business never gets this one\'s product');
    // same-origin product photo for the dashboard (its CSP only allows images from itself)
    $ph = $h->req('GET', '/media/photo/' . $tid . '/TS-001'); eq($ph['code'], 200, 'the product picture, re-encoded for the dashboard'); ok(strpos($ph['body'], "\xFF\xD8") === 0, 'as a JPEG'); Db::update('store_products', ['image_url' => null], 'tenant_id=? AND sku=?', [$tid, 'TS-001']); eq($h->req('GET', '/media/photo/' . $tid . '/TS-001')['code'], 404, 'no picture set: 404, the card shows the initial instead'); eq($h->req('GET', '/media/photo/' . $tid . '/..%2f..')['code'], 404);
});

t('product pictures: built-in illustrations for every product, only ever this business\'s own, never replacing a photo link', function () use ($h, $mk4, $path4) {
    $v = $mk4('Art'); $tid = $v['tid']; eq((int)Db::val("SELECT COUNT(*) FROM store_products WHERE tenant_id=? AND (image_url IS NULL OR image_url='')", [$tid]), 0, 'sample products come with pictures');
    foreach (Db::all("SELECT sku FROM store_products WHERE tenant_id=?", [$tid]) as $r) { $x = $h->req('GET', '/media/art/' . $tid . '/' . $r['sku']); eq($x['code'], 200, $r['sku']); ok(strpos($x['body'], "\x89PNG") === 0); $sz = getimagesizefromstring($x['body']); eq([$sz[0], $sz[1]], [800, 800]); }
    eq(\CaliChat\Services\ProductArt::kind(['name' => 'Slim Fit Jeans']), 'jeans'); eq(\CaliChat\Services\ProductArt::kind(['name' => 'Mystery thing']), 'box'); ok(\CaliChat\Services\ProductArt::isArtUrl('media/art/3/TS-001') && !\CaliChat\Services\ProductArt::isArtUrl('media/art/3/../../x') && !\CaliChat\Services\ProductArt::isArtUrl('http://evil/x'));
    Store::saveProduct($tid, ['sku' => 'NEW-9', 'name' => 'Cap', 'price' => 10, 'image_url' => 'media/art/999/NEW-9']); eq(Db::val("SELECT image_url FROM store_products WHERE tenant_id=? AND sku='NEW-9'", [$tid]), 'media/art/' . $tid . '/NEW-9', 'another business\'s picture path is rewritten to our own');
    throws(fn() => Store::saveProduct($tid, ['sku' => 'NEW-8', 'name' => 'X', 'price' => 1, 'image_url' => 'ftp://x/y.jpg']), 'other links are still refused');
    Store::saveProduct($tid, ['sku' => 'NEW-7', 'name' => 'No pic', 'price' => 1]); Store::saveProduct($tid, ['sku' => 'NEW-6', 'name' => 'Own photo', 'price' => 1, 'image_url' => 'https://cdn.example.lk/own.jpg']);
    eq(Store::addPictures($tid), 1, 'only the product without a picture'); eq(Db::val("SELECT image_url FROM store_products WHERE tenant_id=? AND sku='NEW-6'", [$tid]), 'https://cdn.example.lk/own.jpg', 'a real photo link is never replaced'); eq(Store::addPictures($tid), 0);
    $page = $h->req('GET', $path4(Catalogue::link($tid, '94770009999'))); preg_match('/"image":"([^"]*TS-001[^"]*)"/', $page['body'], $m); ok($m && strpos(stripslashes($m[1]), '/media/art/' . $tid . '/TS-001') !== false && strpos(stripslashes($m[1]), 'http') === 0, 'the catalogue page gets full URLs for the pictures');
    Db::update('store_products', ['is_active' => 0], 'tenant_id=? AND sku=?', [$tid, 'TS-001']); eq($h->req('GET', '/media/art/' . $tid . '/TS-001')['code'], 404, 'hidden products have no public picture'); eq($h->req('GET', '/media/art/' . $tid . '/NOPE-1')['code'], 404);
    $p = Db::one("SELECT * FROM store_products WHERE tenant_id=? AND sku='JN-015'", [$tid]); $card = Brand::cardPng($tid, $p); ok($card !== null && strlen($card) < 200000, 'the WhatsApp card now carries the picture and stays small');
});

t('hand-back: a person returns a chat to the AI with an optional note; a waiting customer message is answered; the note reaches the prompt once', function () use ($mk4) {
    $v = $mk4('Back'); $tid = $v['tid']; $c = new Http('http://127.0.0.1:8765'); $c->login($v['email']); $csrf = $c->meta();
    $mkConv = function (string $ext, string $lastSender) use ($tid) { $ct = Chat::contact($tid, 0, 'whatsapp', $ext, 'Cust ' . $ext, $ext); $cv = Chat::conversation($tid, null, 'whatsapp', $ct, null); Chat::addMessage($tid, (int)$cv['id'], 'in', 'customer', 'Where is my refund?'); if ($lastSender === 'human') Chat::addMessage($tid, (int)$cv['id'], 'out', 'human', 'Refund approved, 3 days.', ['user' => 'Agent']); Db::update('conversations', ['status' => 'human', 'handoff_reason' => 'refund'], 'id=?', [$cv['id']]); return (int)$cv['id']; };
    $a = $mkConv('94772220001', 'customer'); $r = $c->api('POST', 'inbox/status', ['id' => $a, 'status' => 'ai', 'note' => "  Refund approved,\n tell them 3 days  "], $csrf); eq($r['code'], 200); $row = Db::one("SELECT * FROM conversations WHERE id=?", [$a]);
    eq($row['status'], 'ai'); eq($row['handback_note'], 'Refund approved, tell them 3 days', 'note is tidied'); eq((int)$row['ai_catchup'], 1, 'the customer is still waiting'); eq($row['handoff_reason'], null); ok(Db::val("SELECT COUNT(*) FROM messages WHERE conversation_id=? AND sender='system' AND content LIKE 'Handed back to the AI by%'", [$a]) == 1, 'a system line shows it in the thread');
    $b = $mkConv('94772220002', 'human'); $c->api('POST', 'inbox/status', ['id' => $b, 'status' => 'ai'], $csrf); $rb = Db::one("SELECT * FROM conversations WHERE id=?", [$b]); eq($rb['status'], 'ai'); eq((int)$rb['ai_catchup'], 0, 'the team already answered: no catch-up'); eq($rb['handback_note'], null);
    $sys = \CaliChat\Services\Agent::systemPrompt(Tenant::get($tid), ['name' => 'Bot', 'business_name' => 'Back', 'tone' => 'friendly', 'languages' => 'English', 'instructions' => ''], ['channel_type' => 'whatsapp', 'name' => 'X'], '', [], '', '', [], '', 'Refund approved, tell them 3 days'); ok(strpos($sys, 'HANDED THIS CHAT BACK') !== false && strpos($sys, 'Refund approved, tell them 3 days') !== false, 'the AI is told');
    $noNote = \CaliChat\Services\Agent::systemPrompt(Tenant::get($tid), ['name' => 'Bot', 'business_name' => 'Back', 'tone' => 'friendly', 'languages' => 'English', 'instructions' => ''], ['channel_type' => 'whatsapp', 'name' => 'X'], '', [], ''); ok(strpos($noNote, 'HANDED THIS CHAT BACK') === false);
    eq($c->api('POST', 'inbox/status', ['id' => $a, 'status' => 'bogus'], $csrf)['code'], 422);
    $c2 = new Http('http://127.0.0.1:8765'); $o = mkTenant('BackOther'); $c2->login($o['email']); eq($c2->api('POST', 'inbox/status', ['id' => $a, 'status' => 'human'], $c2->meta())['code'], 404, 'another business cannot touch it');
    $conv = Db::one("SELECT * FROM conversations WHERE id=?", [$a]); $ch = Db::insert('channels', ['tenant_id' => $tid, 'type' => 'whatsapp', 'name' => 'W', 'external_id' => '8104', 'verify_token' => 'v', 'channel_key' => bin2hex(random_bytes(8)), 'status' => 'active']); Db::update('conversations', ['channel_id' => $ch], 'id=?', [$a]);
    $n = Jobs::catchUp(); eq($n, 1, 'the waiting message is picked up'); eq((int)Db::val("SELECT ai_catchup FROM conversations WHERE id=?", [$a]), 0, 'only once'); ok((int)Db::val("SELECT COUNT(*) FROM messages WHERE conversation_id=? AND sender='ai'", [$a]) >= 1, 'the AI answered (here with its fallback: no Gemini key in tests)'); eq(Jobs::catchUp(), 0);
});

t('setup guide: what the owner types is saved and shown again; store details save the brand, fee and payments', function () use ($mk4) {
    $v = mkTenant('Setup'); $tid = $v['tid']; $c = new Http('http://127.0.0.1:8765'); $c->login($v['email']); $csrf = $c->meta(); $post = fn(array $d) => $c->req('POST', '/app/onboarding', http_build_query(['_csrf' => $csrf] + $d));
    $post(['act' => 'agent', 'mode' => 'draft', 'description' => 'We sell shoes and bags in Colombo, delivery 350 rupees, friendly tone.', 'instructions' => '']); eq(Tenant::get($tid)['cfg']['agent_description'], 'We sell shoes and bags in Colombo, delivery 350 rupees, friendly tone.', 'the description is kept even when drafting is not possible');
    $page = $c->req('GET', '/app/onboarding')['body']; ok(strpos($page, 'We sell shoes and bags in Colombo') !== false, 'and shown again'); ok(strpos($page, 'no Gemini API key') !== false || strpos($page, 'could not draft') !== false, 'with an honest reason; flash was: ' . (preg_match('#class="flash[^"]*"[^>]*>(.*?)</div>#s', $page, $fm) ? $fm[1] : 'none'));
    $mine = 'You are the assistant for Setup Shoes. Be friendly, quote prices only from tools, and hand over refunds to a person.'; $post(['act' => 'agent', 'mode' => 'own', 'description' => 'x', 'instructions' => $mine]); eq(Db::val("SELECT instructions FROM agents WHERE tenant_id=?", [$tid]), $mine, 'own instructions are saved'); ok(strpos($c->req('GET', '/app/onboarding')['body'], 'quote prices only from tools') !== false, 'and shown');
    $post(['act' => 'agent', 'mode' => 'own', 'description' => 'keep me', 'instructions' => 'too short']); $p2 = $c->req('GET', '/app/onboarding')['body']; ok(strpos($p2, 'too short') !== false && strpos($p2, 'keep me') !== false, 'a rejected save keeps what was typed'); eq(Db::val("SELECT instructions FROM agents WHERE tenant_id=?", [$tid]), $mine, 'and does not overwrite the saved text');
    $post(['act' => 'store_details', 'name' => 'Setup Shoes', 'brand_name' => 'Setup & Co', 'brand_tagline' => 'Walk well', 'brand_color' => '#0F766E', 'brand_phone' => '0112223334', 'brand_address' => '1 Main St', 'default_fee' => '400', 'free_over' => '9000', 'payments' => ['Cash on delivery', 'Bank transfer', 'Barter'], 'invoice_info' => 'Bank 123']);
    $cfg = Tenant::get($tid)['cfg']; $b = Brand::get($tid); eq($b['name'], 'Setup & Co'); eq($b['brand_color'], '#0F766E'); eq($b['brand_phone'], '0112223334'); eq((float)$cfg['store_default_fee'], 400.0); eq((float)$cfg['store_free_over'], 9000.0); eq($cfg['store_payments'], 'Cash on delivery,Bank transfer', 'unknown payment methods are dropped'); eq($cfg['store_invoice_info'], 'Bank 123'); ok($cfg['brand_done']);
    ok(array_column(\CaliChat\Services\Onboarding::steps($tid), 'done', 'key')['store_details'], 'the step turns green'); ok(strpos($c->req('GET', '/app/onboarding')['body'], 'Setup &amp; Co') !== false, 'saved values are shown (and escaped)');
    $s = mkTenant('SetupStaff', 'agent'); Db::update('users', ['tenant_id' => $tid], 'id=?', [$s['uid']]); $c2 = new Http('http://127.0.0.1:8765'); $c2->login($s['email']); $c2->req('POST', '/app/onboarding', http_build_query(['_csrf' => $c2->meta(), 'act' => 'store_details', 'name' => 'Hacked'])); eq(Db::val("SELECT name FROM tenants WHERE id=?", [$tid]), 'Setup Shoes', 'staff cannot change store details');
});

t('catalogue designer: owners design it with a live preview; members need store_edit; designs are per business', function () use ($mk4, $h) {
    $v = $mk4('Design'); $tid = $v['tid']; $other = $mk4('DesignTwo'); $c = new Http('http://127.0.0.1:8765'); $c->login($v['email']); $csrf = $c->meta();
    $page = $c->req('GET', '/app/catalogue'); eq($page['code'], 200); ok(strpos($page['body'], 'Catalogue') !== false && strpos($page['body'], 'Live preview') !== false && strpos($page['body'], 'catalogue_designer.js') !== false); ok(preg_match('#<iframe id="pv"[^>]+data-src="([^"]+/shop/' . $tid . '/preview/[^"]+)"#', $page['body'], $m) === 1, 'the preview link is signed');
    $pv = html_entity_decode($m[1]); $live = $h->req('GET', preg_replace('#^https?://[^/]+#', '', $pv) . '?d[cat_theme]=brand&d[brand_name]=Unsaved+Name&d[cat_columns]=2&d[_catalogue_form]=1'); eq($live['code'], 200); ok(strpos($live['body'], 'Unsaved Name') !== false && strpos($live['body'], '"theme":"brand"') !== false, 'unsaved values show in the preview'); ok(Brand::get($tid)['name'] !== 'Unsaved Name', 'and are not saved');
    $liveBad = $h->req('GET', preg_replace('#^https?://[^/]+#', '', $pv) . '?d[brand_color]=red&d[cat_layout][]=x'); eq($liveBad['code'], 200, 'junk preview values cannot break the page');
    $c->req('POST', '/app/catalogue', http_build_query(['_csrf' => $csrf, 'act' => 'brand_save', '_catalogue_form' => 1, 'brand_name' => 'Design House', 'brand_color' => '#C2410C', 'cat_layout' => 'grid', 'cat_theme' => 'light', 'cat_corner' => 'square', 'cat_columns' => 4, 'cat_sort' => 'price_desc', 'cat_title' => 'All styles', 'cat_button' => 'Buy now', 'cat_show_sku' => 1, 'cat_hide_categories' => ['Bags']]));
    $b = Brand::get($tid); eq([$b['name'], $b['brand_color'], $b['cat_layout'], $b['cat_corner'], $b['cat_columns'], $b['cat_sort'], $b['cat_button'], $b['cat_show_sku'], $b['cat_show_stock'], $b['hidden_categories']], ['Design House', '#C2410C', 'grid', 'square', 4, 'price_desc', 'Buy now', 1, 0, ['Bags']]);
    eq(Brand::get($other['tid'])['name'], 'DesignTwo', 'another business is untouched'); $items = Catalogue::products($tid, $b); ok($items[0]['price'] >= $items[1]['price'], 'sorted by price, high to low'); ok(!in_array('Bags', Catalogue::categories($items), true));
    $s = mkTenant('DesignStaff', 'agent'); Db::update('users', ['tenant_id' => $tid], 'id=?', [$s['uid']]); $c2 = new Http('http://127.0.0.1:8765'); $c2->login($s['email']); $cs = $c2->meta(); eq($c2->req('GET', '/app/catalogue')['code'], 200, 'members may look');
    $c2->req('POST', '/app/catalogue', http_build_query(['_csrf' => $cs, 'act' => 'brand_save', 'brand_name' => 'Hacked'])); eq(Brand::get($tid)['name'], 'Design House', 'but need store_edit to change it');
    $o = new Http('http://127.0.0.1:8765'); $x = mkTenant('DesignAttacker'); $o->login($x['email']); $o->req('POST', '/app/catalogue', http_build_query(['_csrf' => $o->meta(), 'act' => 'brand_save', 'brand_name' => 'Other tenant', 'tenant_id' => $tid])); eq(Brand::get($tid)['name'], 'Design House', 'the tenant always comes from the session');
});
